inline constexpr GuideTip ptTips[] = {
    {"WILD POKéMON","Why did the POKéMON in this grass change?","Look at the clock.","Two of the grass's slots follow the clock: one pair of POKéMON in the morning (4 AM to 10 AM), another by day (until 8 PM) and another at night. HERE shows the list for the time on your DS clock, which is your device's.",0,0,""},
    {"FIELD MOVES","Which badge lets me use each HM outside battle?","Each one has its own badge.","ROCK SMASH needs the COAL BADGE (ROARK), CUT the FOREST BADGE (GARDENIA), DEFOG the RELIC BADGE (FANTINA), FLY the COBBLE BADGE (MAYLENE), SURF the FEN BADGE (CRASHER WAKE), STRENGTH the MINE BADGE (BYRON), ROCK CLIMB the ICICLE BADGE (CANDICE) and WATERFALL the BEACON BADGE (VOLKNER).",0,0,""},
};
inline constexpr GuideTip ptStuck[] = {
    {"BLOCKED PATHS","PSYDUCK block ROUTE 210","A medicine.","They need the SECRETPOTION, which CYNTHIA gives you at VALOR LAKEFRONT. Talk to them with it in your bag.",464,0,"ROUTE210"},
    {"BLOCKED PATHS","Thick fog on ROUTE 210","A field move clears it.","Use DEFOG (HM05, from the SOLACEON RUINS; it needs the RELIC BADGE).",424,0,"ROUTE210"},
    {"BLOCKED PATHS","The VALLEY WINDWORKS is locked","Somebody has the key.","Beat the grunts in FLOAROMA MEADOW: one of them drops the WORKS KEY there.",438,0,"VALLEYWINDWORKS|FLOAROMAMEADOW"},
    {"BLOCKED PATHS","Can't get into the GALACTIC WAREHOUSE","A key in VEILSTONE CITY.","It opens with the STORAGE KEY. After what happens at LAKE ACUITY, a grunt turns up in VEILSTONE CITY: talk to him and he drops it.",463,0,"VEILSTONECITY"},
    {"BLOCKED PATHS","Locked doors in the GALACTIC HQ","Look downstairs.","The GALACTIC KEY is an item ball on the HQ's B2F.",440,0,"VEILSTONECITY"},
    {"BLOCKED PATHS","Rocks in the way","A field move.","Small cracked rocks break with ROCK SMASH, big round ones move with STRENGTH, rocky walls are climbed with ROCK CLIMB. WHERE IS has each HM.",0,0,""},
};
