inline constexpr GuideTip hgTips[] = {
    {"WILD POKéMON","Why did the POKéMON on this route change?","Look at the clock.","The grass has a list for the morning (4 AM to 10 AM), the day (until 8 PM) and the night. At night the GOOD and SUPER ROD can also hook a night fish. HERE shows the list for the time on your DS clock, which is your device's.",0,0,""},
    {"FIELD MOVES","Which badge lets me use each HM outside battle?","Each one has its own badge.","ROCK SMASH needs the ZEPHYR BADGE (FALKNER), CUT the HIVE BADGE (BUGSY), STRENGTH the PLAIN BADGE (WHITNEY), SURF the FOG BADGE (MORTY), FLY the STORM BADGE (CHUCK), WHIRLPOOL the GLACIER BADGE (PRYCE), WATERFALL the RISING BADGE (CLAIR) and ROCK CLIMB the EARTH BADGE (BLUE).",0,0,""},
    {"FIELD MOVES","CLAIR didn't give me a badge","Behind her gym.","Beating her only lets you into the DRAGON'S DEN behind her gym. The elder in its shrine gives you the RISING BADGE once you've answered his questions; a wrong answer just gets the question again.",0,0,""},
};
inline constexpr GuideTip hgStuck[] = {
    {"JOHTO","An odd tree blocks ROUTE 36","It wants water.","Water it with the SQUIRTBOTTLE, from GOLDENROD's flower shop once you have WHITNEY's badge. It's a POKéMON, and the battle starts.",477,0,"ROUTE36"},
    {"JOHTO","ECRUTEAK's gym won't let me in","The tower in town.","Go down into the BURNED TOWER first: the gym opens after what happens on its lowest floor.",0,0,"ECRUTEAKCITY"},
    {"JOHTO","JASMINE isn't in OLIVINE's gym","The lighthouse.","She's at the top of the lighthouse with a sick AMPHAROS. Talk to her, get the SECRETPOTION from CIANWOOD's pharmacy, and bring it back to her.",464,0,"OLIVINECITY|CIANWOODCITY"},
    {"JOHTO","How do I get to CIANWOOD CITY?","Across the water.","Over the sea west of OLIVINE CITY: you need SURF.",0,0,"OLIVINECITY"},
    {"JOHTO","Someone blocks PRYCE's gym in MAHOGANY TOWN","The LAKE OF RAGE first.","After the red GYARADOS at the LAKE OF RAGE, talk to LANCE there, then go into MAHOGANY's souvenir shop. Clearing TEAM ROCKET's hideout behind it moves him (and ends ROUTE 43's toll).",0,202,"MAHOGANYTOWN|LAKEOFRAGE|ROUTE43"},
    {"JOHTO","TEAM ROCKET took the RADIO TOWER","Two keys.","It starts once you hold the FOG, STORM, MINERAL and GLACIER BADGES. The fake director on the top floor drops the BASEMENT KEY; it opens a door in the GOLDENROD TUNNEL, where the real director gives you the CARD KEY for the tower's third floor.",0,198,"GOLDENRODCITY"},
    {"JOHTO","The road east of MAHOGANY TOWN, or BLACKTHORN's gym, is blocked","GOLDENROD first.","Both clear once TEAM ROCKET is out of the RADIO TOWER.",0,198,"MAHOGANYTOWN|BLACKTHORNCITY"},
    {"JOHTO","I'm stopped at NEW BARK TOWN's east exit","A legendary POKéMON.","After the RISING BADGE, see PROF. ELM, then go to ECRUTEAK, get the CLEAR BELL in the DANCE THEATER and face HO-OH on the roof of the BELL TOWER. The road to the LEAGUE opens after that.",0,0,"NEWBARKTOWN"},
    {"KANTO","The power is out","CERULEAN CITY.","Talk to the POWER PLANT's manager, then go into CERULEAN's gym, follow MISTY to ROUTE 25, and beat the grunt on ROUTE 24. The MACHINE PART then turns up in CERULEAN's gym: bring it back to the manager.",0,280,"ROUTE10|CERULEANCITY|ROUTE24|ROUTE25"},
    {"KANTO","VIRIDIAN's gym is locked","CINNABAR ISLAND.","Win seven of KANTO's badges, then find BLUE on CINNABAR ISLAND and talk to him.",0,0,"VIRIDIANCITY|CINNABARISLAND"},
    {"KANTO","A big POKéMON sleeps by DIGLETT'S CAVE","Music wakes it.","Play the POKé FLUTE station on your POKéGEAR's radio (it needs the EXPN CARD) and talk to it.",0,287,"ROUTE11"},
    {"KANTO","How do I get to MT. SILVER?","PROF. OAK.","Beat BLUE in VIRIDIAN CITY, then see PROF. OAK in PALLET TOWN: he gives you ROCK CLIMB and has the guard at the LEAGUE's gate let you through to ROUTE 28.",0,299,"PALLETTOWN|ROUTE28"},
    {"KANTO","When does the S.S. AQUA sail?","Weekdays.","Once you're in the HALL OF FAME and have the S.S. TICKET. After the first trip it leaves OLIVINE on Monday and Friday, VERMILION on Sunday and Wednesday.",456,0,"OLIVINECITY|VERMILIONCITY"},
};
