inline constexpr GuideTip black2Tips[] = {
    {"WILD POKéMON","Why did the POKéMON here change?","Look at the calendar.","Some places change their POKéMON with the seasons, and the seasons follow the month: January, May and September are spring, February, June and October summer, March, July and November autumn, April, August and December winter. HERE shows this month's list, by your DS clock (your device's).",0,0,""},
    {"WILD POKéMON","What about the dark grass and the grass that shakes?","They're not the plain grass.","Dark grass, grass that shakes and water that ripples each hold POKéMON of their own, often stronger or rarer than the plain grass around them.",0,0,""},
    {"BOSSES","Why does NEXT BOSS show two teams?","It depends on the game's mode.","Every leader, the ELITE FOUR and the CHAMPION bring one team in the normal game and a bigger one with CHALLENGE MODE on. Easy mode uses the normal team at lower levels.",0,0,""},
    {"BOSSES","Do the ELITE FOUR change after the ending?","Think about the HALL OF FAME.","Yes. Once you have entered the HALL OF FAME, the ELITE FOUR and the CHAMPION come back with stronger teams, and NEXT BOSS shows those.",0,0,""},
};
